import{_ as i}from"./chunks/SnowShot_2025-10-28_03-06-15.DhGsC_HV.js";import{_ as a,o as r,c as o,b3 as t}from"./chunks/framework.VnelH-cX.js";const m=JSON.parse('{"title":"文本提取","description":"","frontmatter":{},"headers":[],"relativePath":"guide/function/detectOcr.md","filePath":"guide/function/detectOcr.md","lastUpdated":1786700458000}'),n={name:"guide/function/detectOcr.md"};function e(s,l,h,g,d,p){return r(),o("div",null,[...l[0]||(l[0]=[t('<h1 id="文本提取" tabindex="-1">文本提取 <a class="header-anchor" href="#文本提取" aria-label="Permalink to &quot;文本提取&quot;">​</a></h1><p>Wing Shot 的文本提取功能通过下载<strong>文本识别</strong>插件开启，启动后将激活强大的 OCR（光学字符识别）能力，让您能够快速从图片、截图中提取文字内容。无论是处理文档、识别图片文字还是提取屏幕内容，文本提取功能都能为您提供高效准确的识别服务。</p><p><img src="'+i+'" alt="文本识别界面"></p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>打开 Wing Shot 界面，点击侧边栏菜单<strong>个性化</strong>下的<strong>插件</strong>打开插件管理页面。接着找到<strong>文本识别</strong>插件，点击<strong>安装</strong>按钮即可完成文本识别插件的安装。</p><h3 id="增强功能" tabindex="-1">增强功能 <a class="header-anchor" href="#增强功能" aria-label="Permalink to &quot;增强功能&quot;">​</a></h3><p>安装<strong>文本识别</strong>插件后，它能和其他插件配合使用，激活更多实用功能：</p><ul><li><strong>配合翻译插件</strong>：激活截图翻译、固定到屏幕翻译等功能</li><li><strong>配合 AI 对话插件</strong>：支持将图片转换为 HTML 和 Markdown 格式，实现智能图片解析</li></ul><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><p>Wing Shot 的文本提取功能为您提供了全方位的文字识别体验：</p><ul><li><strong>高精度识别</strong>：采用先进的 OCR 技术，准确识别各类图片和截图中的文字</li><li><strong>多语言支持</strong>：支持中文、英文、日文等多种语言的文字识别</li><li><strong>开箱即用</strong>：Wing Shot 默认提供了开箱可用的文本识别服务，无需额外配置即可使用</li><li><strong>截图识别</strong>：在截图编辑界面直接进行文字识别，识别结果一键复制</li><li><strong>快捷识别</strong>：通过全局快捷键快速截图并自动识别文字内容</li><li><strong>翻译集成</strong>：配合翻译插件，可实现截图后自动识别并翻译</li><li><strong>智能转换</strong>：配合 AI 对话插件，可将图片智能转换为 HTML 或 Markdown 格式</li></ul><h2 id="截图文本识别" tabindex="-1">截图文本识别 <a class="header-anchor" href="#截图文本识别" aria-label="Permalink to &quot;截图文本识别&quot;">​</a></h2><p>安装<strong>文本识别</strong>插件后，在截图编辑界面的工具栏中会自动增加<strong>文本识别</strong>工具图标。</p><h3 id="基本使用" tabindex="-1">基本使用 <a class="header-anchor" href="#基本使用" aria-label="Permalink to &quot;基本使用&quot;">​</a></h3><p>在截图编辑过程中使用文本识别：</p><ol><li><strong>进行截图</strong>：使用任意方式触发截图功能</li><li><strong>框选区域</strong>：框选需要识别文字的区域（可选，不框选则识别整个截图）</li><li><strong>点击识别工具</strong>：点击工具栏中的<strong>文本识别</strong>图标</li><li><strong>获取结果</strong>：识别完成后，文字内容会自动显示在结果窗口中</li><li><strong>复制使用</strong>：点击复制按钮即可将识别的文字复制到剪贴板</li></ol><h3 id="识别结果操作" tabindex="-1">识别结果操作 <a class="header-anchor" href="#识别结果操作" aria-label="Permalink to &quot;识别结果操作&quot;">​</a></h3><p>文字识别完成后，您可以对结果进行以下操作：</p><ul><li><strong>一键复制</strong>：快速复制识别的文字内容到剪贴板</li><li><strong>重新识别</strong>：如果识别结果不理想，可以重新选择区域再次识别</li><li><strong>配合翻译</strong>：如果安装了翻译插件，可以使用<strong>文本识别翻译</strong>工具一键完成识别和翻译</li></ul><h2 id="快捷功能" tabindex="-1">快捷功能 <a class="header-anchor" href="#快捷功能" aria-label="Permalink to &quot;快捷功能&quot;">​</a></h2><p>Wing Shot 提供了强大的文本识别快捷功能，让您能够在任何场景下快速进行文字提取。</p><h3 id="配置快捷键" tabindex="-1">配置快捷键 <a class="header-anchor" href="#配置快捷键" aria-label="Permalink to &quot;配置快捷键&quot;">​</a></h3><ol><li>在侧边栏点击<strong>快捷功能</strong>菜单</li><li>找到文本识别相关的快捷键配置项</li><li>点击按键录入按钮然后录制所需的组合快捷键</li><li>录入后点击确认即可生效</li></ol><h3 id="快捷识别场景" tabindex="-1">快捷识别场景 <a class="header-anchor" href="#快捷识别场景" aria-label="Permalink to &quot;快捷识别场景&quot;">​</a></h3><p>配置快捷键后，您可以在以下场景快速进行文字识别：</p><h4 id="快速截图识别" tabindex="-1">快速截图识别 <a class="header-anchor" href="#快速截图识别" aria-label="Permalink to &quot;快速截图识别&quot;">​</a></h4><p>使用步骤：</p><ol><li>按下快速截图识别快捷键</li><li>框选需要识别文字的屏幕区域</li><li>点击<strong>文本识别</strong>工具，自动完成文字识别并显示结果</li></ol><p>适用场景：</p><ul><li>提取图片中的文字内容</li><li>识别网页中无法复制的文字</li><li>提取 PDF 文档中的文字</li><li>识别视频字幕或截图文字</li><li>数字化纸质文档内容</li></ul><h4 id="截图识别翻译" tabindex="-1">截图识别翻译 <a class="header-anchor" href="#截图识别翻译" aria-label="Permalink to &quot;截图识别翻译&quot;">​</a></h4><p>需要同时安装<strong>翻译</strong>插件。</p><p>使用步骤：</p><ol><li>按下截图翻译快捷键</li><li>框选需要翻译的屏幕区域</li><li>点击<strong>文本识别翻译</strong>工具即可自动完成识别和翻译</li></ol><p>适用场景：</p><ul><li>阅读外文图片或文档</li><li>翻译游戏或软件界面文字</li><li>处理外文截图内容</li><li>识别并翻译图表中的文字</li></ul><h2 id="ai-智能转换" tabindex="-1">AI 智能转换 <a class="header-anchor" href="#ai-智能转换" aria-label="Permalink to &quot;AI 智能转换&quot;">​</a></h2><p>当同时安装<strong>文本识别</strong>插件和 <strong>AI 对话</strong>插件时，可以使用 AI 的强大能力将图片智能转换为结构化的 HTML 或 Markdown 格式。这个功能特别适合需要将截图内容转换为可编辑文档的场景。</p><h3 id="图片转-html" tabindex="-1">图片转 HTML <a class="header-anchor" href="#图片转-html" aria-label="Permalink to &quot;图片转 HTML&quot;">​</a></h3><p>将截图或图片转换为 HTML 格式，保留原有的布局和样式结构。</p><p>使用步骤：</p><ol><li>进行截图或选择需要转换的图片内容</li><li>在文本识别工具栏中点击 <strong>转换为 HTML</strong> 工具</li><li>AI 会自动分析图片内容并生成相应的 HTML 代码</li><li>查看生成结果，一键复制 HTML 代码</li></ol><p>适用场景：</p><ul><li>将网页设计稿转换为 HTML 代码</li><li>快速实现界面原型的代码转换</li><li>将图片中的表格转换为 HTML 表格</li><li>提取图片中的布局结构并代码化</li><li>将手绘线框图转换为可用的 HTML 框架</li></ul><h3 id="图片转-markdown" tabindex="-1">图片转 Markdown <a class="header-anchor" href="#图片转-markdown" aria-label="Permalink to &quot;图片转 Markdown&quot;">​</a></h3><p>将截图或图片转换为 Markdown 格式，适合快速创建文档和笔记。</p><p>使用步骤：</p><ol><li>进行截图或选择需要转换的图片内容</li><li>在截图编辑工具栏中点击 <strong>转换为 Markdown</strong> 工具</li><li>AI 会自动识别图片中的文字、标题、列表等结构</li><li>生成格式化的 Markdown 文档，可直接复制使用</li></ol><p>适用场景：</p><ul><li>将文档截图转换为可编辑的 Markdown 文本</li><li>提取演示文稿内容到笔记中</li><li>将图片中的列表、表格转换为 Markdown 格式</li><li>快速整理图片资料为文档</li><li>将书籍或论文截图转换为可编辑文本</li></ul>',50)])])}const b=a(n,[["render",e]]);export{m as __pageData,b as default};
